  "d": 2,
  "en": "The rate of reaction is concerned with decrease in concentration of reactants or increase in the concentration of products per unit time. It can be expressed as instantaneous rate at a particular instant of time and average rate over a large interval of time. Mathematical representation of rate of reaction is given by rate law. Rate constant and order of a reaction can be determined from rate law or its integrated rate equation. . (i) What is average rate of reaction ? 1 (ii) Write two factors that affect the rate of reaction. 1 (iii) (1) What happens to rate of reaction for zero order reaction ? (2) What is the unit of k for zero order reaction ? 2 1=2 OR (iii) (1) For a reaction P + 2Q Products Rate = k[P]1/2 [Q]1. What is the order of the reaction ? (2) Define pseudo first order reaction with an example. 2 1=2",
