  "d": 2,
  "en": "In coordination compounds, metals show two types of linkages, primary and secondary. Primary valencies are ionisable and are satisfied by negatively charged ions. Secondary valencies are non-ionisable and are satisfied by neutral or negative ions having lone pair of electrons. Primary valencies are non-directional while secondary valencies decide the shape of the complexes. (i) If PtCl2 . 2NH3 does not react with AgNO3, what will be its formula ? 1 (ii) What is the secondary valency of [Co(en)3]3+ ? 1 (iii) (1) Write the formula of Iron(III)hexacyanidoferrate(II). (2) Write the IUPAC name of [Co(NH3)5Cl] Cl2. 2 1=2 OR (iii) Write the hybridization and magnetic behaviour of [Ni(CN)4]2 . 2 [Atomic number : Ni = 28] . SECTION E",
