  "d": 2,
  "en": "The carbon – oxygen double bond is polarised in aldehydes and ketones due to higher electronegativity of oxygen relative to carbon. Therefore they undergo nucleophilic addition reactions with a number of nucleophiles such as HCN, NaHSO3, alcohols, ammonia derivatives and Grignard reagents. Aldehydes are easily oxidised by mild oxidising agents as compared to ketones. The carbonyl group of carboxylic acid does not give reactions of aldehydes and ketones. Carboxylic acids are considerably more acidic than alcohols and most of simple phenols. Answer the following : (a) Write the name of the product when an aldehyde reacts with excess alcohol in presence of dry HCl. 1 (b) Why carboxylic acid is a stronger acid than phenol ? 1 . (c) (i) Arrange the following compounds in increasing order of their reactivity towards CH3MgBr : CH3CHO, (CH3)3C – C || O – CH3, CH3 – C || O – CH3 (ii) Write a chemical test to distinguish between propanal and propanone. 2 1 OR (c) Write the main product in the following : (i) [Ag(NH3)2]+ (ii) H2NCONHNH2 2 1",
